const values = [30, 55, 80, 45, 120, 90, 60, 100];
const peak = Math.max(...values);
const out = [
  { payload: { wake: true } },
  { payload: { clear: 'white' } },
  { payload: { rect: { x: 2, y: 2, w: 100, h: 208, color: 'black', fill: false } } },
  { payload: { rect: { x: 3, y: 3, w: 98, h: 24, color: 'black', fill: true } } },
  { payload: { line: { x0: 10, y0: 190, x1: 95, y1: 190, color: 'black' } } },
  { payload: { line: { x0: 10, y0: 60, x1: 10, y1: 190, color: 'black' } } },
];
values.forEach((v, i) => out.push({ payload: { rect: { x: 14 + i * 10, y: 190 - v, w: 8, h: v, color: 'black', fill: v === peak } } }));
out.push({ payload: { show: true } });
return [out];
